def affine_matrix(M,scale,offsets):
 M=sp.Matrix(M); out=M.copy();out[:,-1]=scale*M[:,-1]+M[:,:-1]*sp.Matrix(offsets);return out

def affine_expr(e,index,scale,offsets):
